from datetime import datetime

# ---- Verification of remaining songs released before 2021 ----

def release_year_from_release_date(rd):
    if isinstance(rd,str) and len(rd)>=4 and rd[:4].isdigit():
        return int(rd[:4])
    return None

token = login_resp['access_token']

# Cache release years
song_year_cache = {}

def get_song_year(sid):
    if sid in song_year_cache:
        return song_year_cache[sid]
    s = apis.spotify.show_song(song_id=sid)
    year = release_year_from_release_date(s.get('release_date'))
    song_year_cache[sid] = year
    return year

# Library check
page_limit=20
page_index=0
current_library=[]
while True:
    resp = apis.spotify.show_song_library(access_token=token, page_index=page_index, page_limit=page_limit)
    if not resp:
        break
    current_library.extend(resp)
    if len(resp)<page_limit:
        break
    page_index += 1

library_pre2021 = []
for s in current_library:
    sid = s['song_id']
    year = get_song_year(sid)
    if year is not None and year < 2021:
        library_pre2021.append((sid,s.get('title'),s.get('added_at'),year))

print('Library songs count now:', len(current_library))
print('Library songs released before 2021 remaining:', len(library_pre2021))
if library_pre2021:
    print('Library pre2021 samples:', library_pre2021[:10])

# Playlist check: fetch all playlists again
page_limit=20
page_index=0
current_playlists=[]
while True:
    resp = apis.spotify.show_playlist_library(access_token=token, page_index=page_index, page_limit=page_limit)
    if not resp:
